FILE: app/src/beacon.ts
```ts
import {
    addAnimationTask,
    createAnimationTask,
    createPropertyAnimationClip,
    createPropertyAnimationGroup,
} from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

/**
 * Starts a repeating warning flash on `lamp.intensity`.
 * Returns a function that sets the peak strength (0 < strength <= 1).
 */
export function startBeacon(
    manager: AnimationManager,
    lamp: { intensity: number },
    periodSeconds: number
): (strength: number) => void {
    // The looping group animates a unit-peak phase; the strength is applied
    // afterwards by a task, so changing it never touches the timing.
    const holder = { phase: 0 };
    let strength = 1;

    const clip = createPropertyAnimationClip("beacon", [
        {
            path: "phase",
            keys: [
                { time: 0, value: 0 },
                { time: 0.1, value: 1 },
                { time: 0.2, value: 0 },
                { time: periodSeconds, value: 0 },
            ],
        },
    ]);

    createPropertyAnimationGroup(manager, holder, clip, {
        loop: true,
        fromTime: 0,
        toTime: periodSeconds,
    });

    // Added after the group, so it runs after the group has written the phase
    // in the same update.
    addAnimationTask(
        manager,
        createAnimationTask(() => {
            lamp.intensity = holder.phase * strength;
        })
    );

    return (s: number) => {
        strength = s;
    };
}
```

I implemented the beacon as a looping property group that animates a unit-peak `phase` (0 → 1 at 0.1 s, back to 0 at 0.2 s, held to the period), plus a task that runs right after it and sets `lamp.intensity = phase * strength`. The group's timing never changes, so a new strength only shows at the next update and the rhythm stays put. I couldn't run or type-check any of it here.

Things I'm unsure of:
- **Exports:** I assumed `createAnimationTask` and `addAnimationTask` are exported from `@babylonjs/lite`, since the notes don't list them among the missing exports.
- **Float32 rounding:** key times are stored as float32, so the 0.1 s and period timings are off by a negligible amount.
- **Blending:** if blending is enabled on a shared manager, my `phase` group is unaffected, because its weight stays 1.
